<?php
require_once __DIR__.'/../config/config.php';$user=require_employee_user();$pdo=db();$employee=employee_owner($pdo,$user);$allowed=ess_request_fields();$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$field=(string)($_POST['requested_field']??'');$value=trim((string)($_POST['requested_value']??''));$reason=trim((string)($_POST['reason']??''));if(!isset($allowed[$field]))$error='That field cannot be requested through ESS.';elseif($value===''||$reason==='')$error='Requested value and reason are required.';else{$old=(string)($employee[$allowed[$field]['column']]??'');$pdo->prepare('INSERT INTO profile_change_requests (employee_id,requester_user_id,request_type,requested_field,old_value,requested_value,reason,supporting_information) VALUES (?,?,?,?,?,?,?,?)')->execute([$employee['id'],$user['id'],$allowed[$field]['type'],$field,$old,$value,$reason,post_value('supporting_information')]);$requestId=(int)$pdo->lastInsertId();audit('EMPLOYEE_SUBMITTED_CHANGE_REQUEST','profile_change_requests',$requestId);notify_roles($pdo,['ADMIN','HR','MANAGER'],'ESS_REQUEST_SUBMITTED','New profile change request',$employee['first_name'].' '.$employee['last_name'].' submitted a '.$allowed[$field]['label'].' change request.');flash('success','Your profile change request was submitted for HR review.');redirect('requests.php');}}$pageTitle='Request profile change';require __DIR__.'/../includes/header.php';?><div class="mb-7"><a href="profile.php" class="text-sm font-bold text-teal-700">← My profile</a><h1 class="font-display text-3xl font-bold mt-2">Request profile change</h1><p class="text-sm text-slate-500 mt-1">Core HR records remain unchanged until HR approves your request.</p></div><?php if($error):?><div class="mb-5 rounded-lg bg-red-50 p-3 text-sm text-red-700"><?=e($error)?></div><?php endif;?><form method="post" class="bg-white border rounded-xl p-6 max-w-2xl space-y-4"><?= csrf_field() ?><label class="block text-sm font-semibold">Field<select name="requested_field" class="field"><option value="">Choose a field</option><?php foreach($allowed as $field=>$definition):?><option value="<?=e($field)?>"><?=e($definition['label'])?></option><?php endforeach;?></select></label><label class="block text-sm font-semibold">Requested value<textarea name="requested_value" required rows="3" class="field"></textarea></label><label class="block text-sm font-semibold">Reason<textarea name="reason" required rows="3" class="field"></textarea></label><label class="block text-sm font-semibold">Supporting information<textarea name="supporting_information" rows="3" class="field"></textarea></label><button class="rounded-lg bg-teal-700 px-5 py-3 text-sm font-bold text-white">Submit request</button></form><?php require __DIR__.'/../includes/footer.php';